\begin{definition}
\label{definition-set-theoretic-equivalence}
Let $S$ be a scheme, and let $B$ be an algebraic space over $S$.
Let $j : R \to U \times_B U$ be a pre-relation over $B$.
\begin{enumerate}
\item We say $j$ is a {\it set-theoretic pre-equivalence relation} if
for all algebraically closed fields $k$ over $B$ the relation
$\sim_R$ on $U(k)$ defined by
$$
\overline{u} \sim_R \overline{u}'
\Leftrightarrow
\begin{matrix}
\exists\text{ field extension }K/k, \ \exists\ r \in R(K), \\
s(r) = \overline{u}, \ t(r) = \overline{u}'
\end{matrix}
$$
is an equivalence relation.
\item We say $j$ is a {\it set-theoretic equivalence relation}
if $j$ is universally injective and a set-theoretic pre-equivalence
relation.
\end{enumerate}
\end{definition}

\begin{lemma}
\label{lemma-category-of-spaces-over-smaller-base-scheme}
Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
The constructions A and B of
Stacks, Section \ref{stacks-section-localize}
above give isomorphisms of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of algebraic}\\
\text{stacks }\mathcal{X}\text{ over }S
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{X}', f)\text{ consisting of an}\\
\text{algebraic stack }\mathcal{X}'\text{ over }S'\text{ and a morphism}\\
f : \mathcal{X}' \to (\Sch/S)_{fppf}\text{ of algebraic stacks over }S'
\end{matrix}
\right\}
$$
\end{lemma}

